import { type CSSProperties, type ReactNode } from "react"
import { LINE_ORDER } from "tfl-ts"
import { ExternalLink, Package } from "lucide-react"
import { cn } from "@/lib/utils"
import { CHIP_CAP_TEXT_BOX_CLASS } from "@/components/tfl/arrivals/chip-text"
import { LineColorBar } from "@/components/tfl/brand/line-badge"
import { StatusDisruptionBlock } from "@/components/tfl/status/status-disruption-copy"
import { LineName } from "@/components/tfl/brand/line-name"
import { TfLRoundel } from "@/components/tfl/brand/tfl-roundel"
import { StationNameTitle } from "@/components/tfl/station-name"
import { getLineNameTiers } from "@/lib/tfl/line-names"
import {
  partitionStatusBoardLines,
  splitByPriority,
} from "@/lib/tfl/status-board"
import type { LineAnnouncement } from "@/lib/tfl/status-reason"
import type { StatusLine } from "@/lib/tfl/status-types"

export type { StatusLine } from "@/lib/tfl/status-types"
export {
  isCurrentAnnouncement,
  isScheduledEngineeringWork,
  prepareLineAnnouncements,
  stripStatusReason,
} from "@/lib/tfl/status-reason"
export type {
  DisruptionStatus,
  LineAnnouncement,
} from "@/lib/tfl/status-reason"

type Props = {
  /** Normalised line status rows from `tfl-ts` (or fixtures). Missing/`undefined` renders empty. */
  data?: readonly StatusLine[]
  children?: ReactNode
  /** When true, omit the page header (useful inside a layout that already has one). */
  hideHeader?: boolean
  /**
   * Watchlist mode: one column, no section title tiles. Pass only the
   * lines you care about as `data`. Empty Good Service is omitted — you
   * will not see "Good Service (0 lines)".
   */
  compact?: boolean
  /**
   * Clock for validity windows and tfl-ts current-row helpers.
   * Pass cache `fetchedAt`. Do not call `Date.now()` in the RSC shell.
   */
  now?: number
  /**
   * Keep operative announcements (`getCurrentLineStatuses`), not `isNow`.
   * Rows with no validity window are live and always kept. Default true.
   * Set `currentOnly={false} dedupe={false} rawReason` for TfL's array verbatim.
   */
  currentOnly?: boolean
  /**
   * Collapse equal or fully contained announcement paragraphs into one,
   * painted at the worse severity. Default true.
   */
  dedupe?: boolean
  /**
   * Keep TfL's raw `reason` string, including mode prefixes such as
   * `LONDON TRAMS:`. Default strips those prefixes.
   */
  rawReason?: boolean
  /**
   * Keep these lines expanded at the top of Service Disruptions.
   * Other disrupted lines collapse to a title and severity. Omit to
   * expand every line.
   */
  priorityLineIds?: readonly string[]
}

/**
 * Modes on TfL’s Tube & Rail status surface (Cable Car is listed separately).
 * Prefer `getCachedLineStatuses()` with no IDs so the client fetches by mode.
 */
export const DEFAULT_STATUS_MODES = [
  "tube",
  "elizabeth-line",
  "dlr",
  "tram",
  "overground",
] as const

/**
 * Tube & Rail lines in `tfl-ts` `LINE_ORDER` (default board sort, no severity).
 * Matches TfL’s Tube / Overground / Elizabeth / DLR / Tram set.
 */
export const DEFAULT_STATUS_BOARD_LINE_IDS = LINE_ORDER

export const DEFAULT_STATUS_LINE_COUNT = DEFAULT_STATUS_BOARD_LINE_IDS.length

/**
 * Curated Underground + Elizabeth subset for demos / Blocks.
 * Fetch with `getCachedLineStatuses(DEFAULT_STATUS_LINE_IDS)` in the app layer
 * and pass `data` plus `now={fetchedAt}`.
 */
export const DEFAULT_STATUS_LINE_IDS = [
  "bakerloo",
  "central",
  "circle",
  "district",
  "elizabeth",
  "hammersmith-city",
  "jubilee",
  "metropolitan",
  "northern",
  "piccadilly",
  "victoria",
  "waterloo-city",
] as const

const OVERGROUND_LINE_IDS = new Set([
  "liberty",
  "lioness",
  "mildmay",
  "suffragette",
  "weaver",
  "windrush",
])

const statusLineModeName = (lineId: string) => {
  if (lineId === "elizabeth") return "elizabeth-line"
  if (OVERGROUND_LINE_IDS.has(lineId)) return "overground"
  if (lineId === "dlr") return "dlr"
  if (lineId === "tram") return "tram"
  return "tube"
}

/** Same tile rhythm as arrivals boards — heights are N × `--arrivals-row`. */
const BOARD_RHYTHM_VARS = {
  "--arrivals-unit": "0.5rem",
  "--arrivals-row": "calc(var(--arrivals-unit) * 6)",
} as CSSProperties

const BOARD_ROOT_CLASS = "flex w-full flex-col text-base @container/status"

const TILE_CLASS =
  "box-border h-[var(--arrivals-row)] min-h-[var(--arrivals-row)] max-h-[var(--arrivals-row)] min-w-0 shrink-0 overflow-clip"

/** Resolves via `data-line` → `--line-color` from tfl-colours tokens. */
const lineTitleClass = "tfl-dark-line-text text-[var(--line-color)]"

const CollapsedDisruptionRow = ({
  lineId,
  modeName,
  name,
  announcements,
  quiet,
}: {
  lineId?: string
  modeName?: string
  name: string
  announcements: readonly LineAnnouncement[]
  quiet?: boolean
}) => {
  const severity = announcements[0]?.statusSeverityDescription?.trim()
  return (
    <details className="group flex flex-col">
      <summary className="cursor-pointer list-none [&::-webkit-details-marker]:hidden">
        <StatusLineHeader
          lineId={lineId}
          modeName={modeName}
          name={name}
          trailing={
            <>
              {severity ? (
                <span className="max-w-[40%] truncate text-base text-muted-foreground">
                  {severity}
                </span>
              ) : null}
              <span
                aria-hidden
                className="ml-1 shrink-0 text-lg leading-none text-muted-foreground transition-transform group-open:rotate-45"
              >
                +
              </span>
            </>
          }
        />
      </summary>
      <StatusDisruptionBlock announcements={announcements} quiet={quiet} />
    </details>
  )
}

const StatusLineHeader = ({
  lineId,
  modeName,
  name,
  trailing,
}: {
  lineId?: string
  modeName?: string
  name: string
  trailing?: ReactNode
}) => (
  <header
    data-line={lineId}
    className={cn("relative flex min-w-0 items-center", TILE_CLASS)}
  >
    <h3
      className={cn(
        "m-0 min-w-0 flex-1 pr-2 text-xl leading-7 font-semibold",
        lineTitleClass
      )}
    >
      <LineName lineId={lineId} name={name} />
    </h3>
    {trailing}
    <div
      className="pointer-events-none absolute inset-x-0 bottom-0"
      aria-hidden
    >
      <LineColorBar lineId={lineId} modeName={modeName} heightClass="h-1" />
    </div>
  </header>
)

const StatusSectionTitle = ({
  title,
  trailing,
  accessibleName,
}: {
  title: string
  trailing?: ReactNode
  accessibleName?: string
}) => (
  <h2
    className={cn(
      "tfl-title m-0 flex h-full min-w-0 items-center text-3xl",
      TILE_CLASS
    )}
    aria-label={accessibleName ?? title}
  >
    <StationNameTitle name={title} />
    {trailing}
  </h2>
)

const StatusSectionHeading = ({
  compact,
  title,
  trailing,
  accessibleName,
}: {
  compact: boolean
  title: string
  trailing?: ReactNode
  accessibleName?: string
}) =>
  compact ? (
    <h2 className="sr-only">{accessibleName ?? title}</h2>
  ) : (
    <StatusSectionTitle
      title={title}
      trailing={trailing}
      accessibleName={accessibleName}
    />
  )

/** Static board chrome — no status data required. */
export const TubeStatusBoardHeader = () => (
  <div className="flex flex-wrap items-center justify-between gap-2">
    <div className="flex items-center gap-3">
      <TfLRoundel className="size-10 lg:size-12" />
      <div>
        <h1 className="scroll-m-20 text-4xl font-extrabold text-balance lg:text-5xl">
          Live TfL Status
        </h1>
        <p className="mt-1 text-base text-muted-foreground">
          Built with{" "}
          <code className="rounded bg-muted px-1 py-0.5 text-xs">tfl-ts</code> +
          open React components
        </p>
      </div>
    </div>
    <div className="flex flex-wrap items-center gap-2">
      <a
        href="https://www.npmjs.com/package/tfl-ts"
        className="flex items-center gap-1 text-blue-500 hover:underline"
        target="_blank"
        rel="noopener noreferrer"
      >
        <Package className="size-4" aria-hidden />
        npm package
        <ExternalLink className="size-4" aria-hidden />
      </a>
      <a
        href="https://github.com/ghcpuman902/tfl-ts"
        className="flex items-center gap-1 text-blue-500 hover:underline"
        target="_blank"
        rel="noopener noreferrer"
      >
        GitHub
        <ExternalLink className="size-4" aria-hidden />
      </a>
    </div>
  </div>
)

type SkeletonProps = {
  /** Line IDs to paint (defaults to `LINE_ORDER` Tube & Rail set). */
  lineIds?: readonly string[]
  /**
   * Watchlist mode: one column, no section title tile. Pass the same
   * `lineIds` you will fetch.
   */
  compact?: boolean
}

/** Titles-only — denser than disruptions. Queries `@container/status`, not the viewport. */
const goodServiceGridClass = (compact: boolean) =>
  compact
    ? "grid grid-cols-1 justify-items-stretch gap-x-4 gap-y-0"
    : "grid grid-cols-2 justify-items-stretch gap-x-4 gap-y-0 @min-[30rem]/status:grid-cols-3 @min-[45rem]/status:grid-cols-5"

/** Prose needs width — fewer columns than Good Service at the same board width. */
const disruptionGridClass = (compact: boolean) =>
  compact
    ? "grid grid-cols-1 gap-x-4"
    : "grid grid-cols-1 gap-x-4 @min-[30rem]/status:grid-cols-2 @min-[45rem]/status:grid-cols-3"

/**
 * Calm loading placeholder — every line in default `LINE_ORDER`,
 * brand bars/titles present but fully desaturated until live data arrives.
 */
export const TubeStatusBoardSkeleton = ({
  lineIds = DEFAULT_STATUS_BOARD_LINE_IDS,
  compact = false,
}: SkeletonProps) => (
  <div
    className={BOARD_ROOT_CLASS}
    style={BOARD_RHYTHM_VARS}
    aria-busy
    aria-label="Loading line status"
  >
    <div>
      <StatusSectionHeading compact={compact} title="Checking the lines..." />
      <div className={goodServiceGridClass(compact)}>
        {lineIds.map((lineId) => {
          const label = getLineNameTiers(lineId).full

          return (
            <div key={lineId} className="saturate-0">
              <StatusLineHeader
                lineId={lineId}
                modeName={statusLineModeName(lineId)}
                name={label}
              />
            </div>
          )
        })}
      </div>
    </div>
  </div>
)

/**
 * Data-aware status board — pass normalised `tfl-ts` line status rows as `data`.
 * Fetching belongs in the app / docs / Block layer (see `getCachedLineStatuses`).
 * Live layout: disruptions (closed sorted last) then good service.
 */
export const TubeStatusBoard = ({
  data,
  hideHeader = false,
  compact = false,
  now,
  currentOnly = true,
  dedupe = true,
  rawReason = false,
  priorityLineIds,
  children,
}: Props) => {
  const { disruptions, goodService } = partitionStatusBoardLines(data ?? [], {
    currentOnly,
    dedupe,
    rawReason,
    now,
  })
  const disruptionSplit = splitByPriority(disruptions, priorityLineIds)

  return (
    <div className={BOARD_ROOT_CLASS} style={BOARD_RHYTHM_VARS}>
      {!hideHeader && (
        <div className="mb-[var(--arrivals-row)]">
          <TubeStatusBoardHeader />
        </div>
      )}

      {disruptions.length > 0 && (
        <div
          className={
            goodService.length > 0
              ? "mb-[calc(var(--arrivals-row)/2)]"
              : undefined
          }
        >
          <StatusSectionHeading compact={compact} title="Service Disruptions" />
          <div className={disruptionGridClass(compact)}>
            {disruptionSplit.priority.map(({ line, announcements, kind }) => {
              return (
                <div key={line.id ?? line.name} className="flex flex-col">
                  <StatusLineHeader
                    lineId={line.id}
                    modeName={line.modeName}
                    name={line.name ?? line.id ?? "Line"}
                  />

                  <StatusDisruptionBlock
                    announcements={announcements}
                    quiet={kind === "closed"}
                  />
                </div>
              )
            })}
            {disruptionSplit.other.map(({ line, announcements, kind }) => (
              <CollapsedDisruptionRow
                key={line.id ?? line.name}
                lineId={line.id}
                modeName={line.modeName}
                name={line.name ?? line.id ?? "Line"}
                announcements={announcements}
                quiet={kind === "closed"}
              />
            ))}
          </div>
        </div>
      )}

      {goodService.length > 0 && (
        <div>
          <StatusSectionHeading
            compact={compact}
            title="Good Service"
            accessibleName={
              !compact && disruptions.length > 0
                ? `Good Service (${goodService.length} lines)`
                : undefined
            }
            trailing={
              !compact && disruptions.length > 0 ? (
                <span
                  className={cn(
                    "ml-2 shrink-0 text-base font-normal text-muted-foreground",
                    CHIP_CAP_TEXT_BOX_CLASS
                  )}
                >
                  ({goodService.length} lines)
                </span>
              ) : null
            }
          />
          <div className={goodServiceGridClass(compact)}>
            {goodService.map(({ line, announcements }) => {
              const infoLabel =
                announcements[0]?.statusSeverityDescription?.trim()
              return (
                <StatusLineHeader
                  key={line.id ?? line.name}
                  lineId={line.id}
                  modeName={line.modeName}
                  name={line.name ?? line.id ?? "Line"}
                  trailing={
                    infoLabel ? (
                      <span className="max-w-[40%] truncate text-base text-muted-foreground">
                        {infoLabel}
                      </span>
                    ) : null
                  }
                />
              )
            })}
          </div>
        </div>
      )}

      {children}
    </div>
  )
}

import { QuietChip } from "@/components/tfl/arrivals/quiet-chip"
import { cn } from "@/lib/utils"

export type StatusDisruptionCopyItem = {
  text: string
  statusSeverityDescription?: string
}

/** Half-tile leading — each wrapped line is exactly `--arrivals-row / 2`. */
export const DISRUPTION_LEADING_CLASS = "leading-[calc(var(--arrivals-row)/2)]"

const DISRUPTION_COPY_CLASS = cn(
  "text-base text-pretty text-foreground/80",
  DISRUPTION_LEADING_CLASS
)

/** `align-top` keeps the 20px chip inside the half-tile line box. */
const SeverityChip = ({ label }: { label: string }) => (
  <QuietChip className="mr-[0.35em] align-top">
    {label}
  </QuietChip>
)

export const StatusDisruptionCopy = ({
  announcement,
  quiet = false,
}: {
  announcement: StatusDisruptionCopyItem
  quiet?: boolean
}) => {
  const severityLabel = announcement.statusSeverityDescription?.trim()
  const body = announcement.text
  const bodyIsOnlyLabel = severityLabel
    ? body.toLowerCase() === severityLabel.toLowerCase()
    : false

  return (
    <p
      className={cn(
        "m-0",
        DISRUPTION_COPY_CLASS,
        quiet && "text-muted-foreground"
      )}
    >
      {severityLabel ? <SeverityChip label={severityLabel} /> : null}
      {bodyIsOnlyLabel ? null : body}
    </p>
  )
}

export const StatusDisruptionBlock = ({
  announcements,
  quiet = false,
}: {
  announcements: readonly StatusDisruptionCopyItem[]
  quiet?: boolean
}) => (
  <div className={DISRUPTION_LEADING_CLASS}>
    {announcements.map((announcement, index) => (
      <StatusDisruptionCopy
        key={index}
        announcement={announcement}
        quiet={quiet}
      />
    ))}
  </div>
)

import {
  getCurrentLineStatuses,
  getStatusKind,
  getWorstCurrentStatus,
} from "tfl-ts"

export type DisruptionStatus = {
  statusSeverity?: number
  statusSeverityDescription?: string
  reason?: string
  disruption?: {
    category?: string
    categoryDescription?: string
  }
  validityPeriods?: {
    isNow?: boolean
    fromDate?: string
    toDate?: string
  }[]
}

const MODE_REASON_PREFIXES = [
  "London Trams",
  "London Tram",
  "London Overground",
  "Docklands Light Railway",
  "Elizabeth line",
  "Elizabeth Line",
  "DLR",
] as const

const escapeRegExp = (value: string) =>
  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")

const lineReasonPrefixes = (line?: {
  name?: string
  modeName?: string
}): string[] => {
  const prefixes: string[] = [...MODE_REASON_PREFIXES]
  const name = line?.name?.trim()
  if (name) {
    const andName = name.replace(/&/g, "and")
    const ampName = name.replace(/\band\b/gi, "&")
    prefixes.push(name, andName, ampName)
    prefixes.push(`London ${name}`, `London ${andName}`, `London ${name}s`)
  }
  const modeName = line?.modeName?.trim().replace(/-/g, " ")
  if (modeName) {
    prefixes.push(modeName, `${modeName} line`)
  }
  return prefixes
}

/** Drop TfL mode / line prefixes that repeat the card title. */
export const stripStatusReason = (
  reason: string,
  line?: { name?: string; modeName?: string }
): string => {
  const prefixes = [...new Set(lineReasonPrefixes(line))].sort(
    (a, b) => b.length - a.length
  )
  const pattern = new RegExp(
    `^(?:${prefixes.map(escapeRegExp).join("|")})(?:\\s+LINE)?\\s*:\\s*`,
    "i"
  )
  return reason.trim().replace(pattern, "")
}

/** Planned / part closure that replaces a service people expected (`PlannedWork`). */
export const isScheduledEngineeringWork = (status: DisruptionStatus): boolean =>
  getStatusKind(status) === "plannedWork"

const periodOverlapsNow = (
  period: NonNullable<DisruptionStatus["validityPeriods"]>[number],
  now: number
): boolean => {
  const from = period.fromDate
    ? Date.parse(period.fromDate)
    : Number.NEGATIVE_INFINITY
  const to = period.toDate
    ? Date.parse(period.toDate)
    : Number.POSITIVE_INFINITY
  if (Number.isNaN(from) || Number.isNaN(to)) return true
  return now >= from && now <= to
}

/**
 * Live-board operative row: RealTime, no validity window, or a window that
 * overlaps `now`. Not `validityPeriods[].isNow` — that tracks RealTime, so a
 * tram Part Closure can be in force today with `isNow: false`.
 *
 * Pass `now` from cache `fetchedAt`. Omit it only when there is no clock
 * (fixtures / tests that do not care about windows).
 */
export const isCurrentAnnouncement = (
  status: DisruptionStatus,
  now?: number
): boolean => {
  if (status.disruption?.category === "RealTime") return true
  const periods = status.validityPeriods ?? []
  if (periods.length === 0) return true
  if (now === undefined) return true
  return periods.some((period) => periodOverlapsNow(period, now))
}

/** Drop standing hours copy once a RealTime Service Closed row is on the card. */
const dropHoursNoticeWhenClosed = (
  statuses: readonly DisruptionStatus[]
): DisruptionStatus[] => {
  const hasClosedRealtime = statuses.some(
    (status) =>
      status.disruption?.category === "RealTime" &&
      getStatusKind(status) === "closed"
  )
  if (!hasClosedRealtime) return [...statuses]
  return statuses.filter(
    (status) => status.disruption?.category !== "Information"
  )
}

const selectAnnouncementStatuses = (
  statuses: readonly DisruptionStatus[],
  options: { currentOnly: boolean; now?: number }
): DisruptionStatus[] => {
  if (!options.currentOnly) return [...statuses]
  const current = getCurrentLineStatuses(
    statuses,
    options.now !== undefined ? { now: options.now } : undefined
  )
  return dropHoursNoticeWhenClosed(
    current.filter((status) => isCurrentAnnouncement(status, options.now))
  )
}

export type LineAnnouncement = {
  /** Paragraph to render (prefix-stripped unless rawReason). */
  text: string
  /** Worst severity in the merged group — drives chip colour. */
  statusSeverity?: number
  statusSeverityDescription?: string
  disruption?: DisruptionStatus["disruption"]
  /** How many TfL rows collapsed into this paragraph. */
  sourceCount: number
}

export type PrepareLineAnnouncementsOptions = {
  line?: { name?: string; modeName?: string }
  /**
   * Keep operative rows from `getCurrentLineStatuses` (default true).
   * Not `isNow`. Pass `now` from cache `fetchedAt`.
   */
  currentOnly?: boolean
  /** Collapse equal / contained paragraphs. Default true. */
  dedupe?: boolean
  /** Keep TfL's unstripped `reason` string. Default false. */
  rawReason?: boolean
  /** Clock for validity windows. Same stamp as tfl-ts `{ now: fetchedAt }`. */
  now?: number
}

const normalizeAnnouncementKey = (text: string): string =>
  text.toLowerCase().replace(/\s+/g, " ").trim()

const resolveAnnouncementText = (
  status: DisruptionStatus,
  options: { line?: { name?: string; modeName?: string }; rawReason: boolean }
): string => {
  const reason = status.reason?.trim()
  if (reason) {
    return options.rawReason ? reason : stripStatusReason(reason, options.line)
  }
  return status.statusSeverityDescription?.trim() || "Status update"
}

type DraftAnnouncement = LineAnnouncement & {
  key: string
}

const toStatusLike = (draft: DraftAnnouncement): DisruptionStatus => ({
  statusSeverity: draft.statusSeverity,
  statusSeverityDescription: draft.statusSeverityDescription,
  disruption: draft.disruption,
})

/**
 * Passenger-facing announcement list for one line: current filter → text
 * resolution → containment dedupe. All three steps are opt-out via options.
 */
export const prepareLineAnnouncements = (
  statuses: readonly DisruptionStatus[],
  options: PrepareLineAnnouncementsOptions = {}
): readonly LineAnnouncement[] => {
  const currentOnly = options.currentOnly ?? true
  const dedupe = options.dedupe ?? true
  const rawReason = options.rawReason ?? false
  const statusNow = options.now !== undefined ? { now: options.now } : undefined

  const resolved = selectAnnouncementStatuses(statuses, {
    currentOnly,
    now: options.now,
  }).map((status) => {
    const text = resolveAnnouncementText(status, {
      line: options.line,
      rawReason,
    })
    return {
      text,
      key: normalizeAnnouncementKey(text),
      statusSeverity: status.statusSeverity,
      statusSeverityDescription: status.statusSeverityDescription,
      disruption: status.disruption,
      sourceCount: 1,
    } satisfies DraftAnnouncement
  })

  const toAnnouncement = (draft: DraftAnnouncement): LineAnnouncement => ({
    text: draft.text,
    statusSeverity: draft.statusSeverity,
    statusSeverityDescription: draft.statusSeverityDescription,
    disruption: draft.disruption,
    sourceCount: draft.sourceCount,
  })

  if (!dedupe) {
    return resolved.map(toAnnouncement)
  }

  const kept: DraftAnnouncement[] = []

  for (const item of resolved) {
    const matchIndex = kept.findIndex(
      (existing) =>
        existing.key === item.key ||
        existing.key.includes(item.key) ||
        item.key.includes(existing.key)
    )

    if (matchIndex === -1) {
      kept.push(item)
      continue
    }

    const existing = kept[matchIndex]!
    const itemLike = toStatusLike(item)
    const existingLike = toStatusLike(existing)
    const preferIncoming =
      item.key.length > existing.key.length ||
      (item.key.length === existing.key.length &&
        getWorstCurrentStatus([itemLike, existingLike], statusNow) === itemLike)

    const winner = preferIncoming ? item : existing
    const loser = preferIncoming ? existing : item
    const winnerLike = preferIncoming ? itemLike : existingLike
    const loserLike = preferIncoming ? existingLike : itemLike
    const worst =
      getWorstCurrentStatus([winnerLike, loserLike], statusNow) ?? winnerLike

    kept[matchIndex] = {
      text: winner.text,
      key: winner.key,
      statusSeverity: worst.statusSeverity,
      statusSeverityDescription: worst.statusSeverityDescription,
      disruption: worst.disruption,
      sourceCount: winner.sourceCount + loser.sourceCount,
    }
  }

  return kept.map(toAnnouncement)
}

import {
  getStatusKind,
  getWorstCurrentStatus,
  sortLinesBySeverityAndOrder,
  type StatusKind,
} from "tfl-ts"
import {
  prepareLineAnnouncements,
  type LineAnnouncement,
  type PrepareLineAnnouncementsOptions,
} from "@/lib/tfl/status-reason"
import type { StatusLine } from "@/lib/tfl/status-types"

export type StatusBoardLine = {
  line: StatusLine
  announcements: readonly LineAnnouncement[]
  kind: StatusKind
}

export type StatusBoardSections = {
  /** Incidents, planned engineering, then timetable-closed (tfl-ts kind order). */
  disruptions: StatusBoardLine[]
  /** Running normally. Access / information notices stay here. */
  goodService: StatusBoardLine[]
}

const sectionForKind = (kind: StatusKind): keyof StatusBoardSections => {
  if (kind === "good" || kind === "info") return "goodService"
  return "disruptions"
}

const announcementKind = (announcement: LineAnnouncement): StatusKind =>
  getStatusKind({
    statusSeverity: announcement.statusSeverity,
    statusSeverityDescription: announcement.statusSeverityDescription,
    disruption: announcement.disruption,
  })

const announcementsForSection = (
  section: keyof StatusBoardSections,
  announcements: readonly LineAnnouncement[]
): readonly LineAnnouncement[] => {
  if (section === "goodService") {
    return announcements.filter(
      (announcement) => announcementKind(announcement) === "info"
    )
  }
  return announcements.filter((announcement) => {
    const kind = announcementKind(announcement)
    return kind !== "good" && kind !== "info"
  })
}

const sortBoardLines = (
  rows: StatusBoardLine[],
  now?: number
): StatusBoardLine[] => {
  if (rows.length <= 1) return rows
  const sorted = sortLinesBySeverityAndOrder(
    rows.map((row) => row.line),
    now !== undefined ? { now } : undefined
  )
  const byKey = new Map(
    rows.map((row) => [row.line.id ?? row.line.name ?? "", row])
  )
  return sorted.flatMap((line) => {
    const key = line.id ?? line.name ?? ""
    const row = byKey.get(key)
    return row ? [row] : []
  })
}

/**
 * Live-board passenger layout. Ranking / “which row is current” stay in tfl-ts.
 * Two sections: disruptions (incident → plannedWork → closed) then good service.
 * Timetable-closed stays in Disruptions, sorted last — not a separate group.
 */
export const partitionStatusBoardLines = (
  lines: readonly StatusLine[],
  options: PrepareLineAnnouncementsOptions = {}
): StatusBoardSections => {
  const buckets: StatusBoardSections = {
    disruptions: [],
    goodService: [],
  }
  const statusNow = options.now !== undefined ? { now: options.now } : undefined

  for (const line of lines) {
    const announcements = prepareLineAnnouncements(line.lineStatuses ?? [], {
      ...options,
      line: options.line ?? { name: line.name, modeName: line.modeName },
    })
    const worst = getWorstCurrentStatus(line.lineStatuses, statusNow)
    const kind = worst ? getStatusKind(worst) : "good"
    const section =
      (options.currentOnly ?? true) && announcements.length === 0
        ? "goodService"
        : sectionForKind(kind)
    buckets[section].push({
      line,
      announcements: announcementsForSection(section, announcements),
      kind,
    })
  }

  return {
    disruptions: sortBoardLines(buckets.disruptions, options.now),
    goodService: sortBoardLines(buckets.goodService, options.now),
  }
}

const lineIdOf = (row: StatusBoardLine): string =>
  row.line.id?.trim() || row.line.name?.trim() || "unknown"

/**
 * Split a already-sorted section into priority vs other without re-sorting.
 * Empty / omitted `priorityLineIds` treats every row as priority.
 */
export const splitByPriority = (
  rows: readonly StatusBoardLine[],
  priorityLineIds: readonly string[] | undefined
): { priority: StatusBoardLine[]; other: StatusBoardLine[] } => {
  if (!priorityLineIds?.length) return { priority: [...rows], other: [] }
  const wanted = new Set(priorityLineIds)
  const priority: StatusBoardLine[] = []
  const other: StatusBoardLine[] = []
  for (const row of rows) {
    ;(wanted.has(lineIdOf(row)) ? priority : other).push(row)
  }
  return { priority, other }
}

/**
 * Chip labels keep normal casing (e.g. “Platform 4”, “Plat 4”).
 * Put this on the painted text node, not the flex chrome — then `items-center`
 * on the chip centres the cap-height box (uppercase X), not the em-square.
 * Chips never show descenders (g/y/p/q), so cap→alphabetic is the optical
 * vertical centre. Do not use x-height (`ex`) trim.
 */
export const CHIP_CAP_TEXT_BOX_CLASS =
  "leading-none [text-box:trim-both_cap_alphabetic]"

/**
 * Shared identity-chip width. Bus routes are ≤4 characters; line codes are
 * 3 letters. One extra `ch` keeps MET / H&C / N253 from clipping.
 */
export const ARRIVALS_IDENTITY_CHIP_WIDTH_CLASS = "w-[5ch]"

/** Unattended rank chip — digit + ordinal suffix (`1st`). */
export const ARRIVALS_RANK_CHIP_WIDTH_CLASS = "w-[3ch]"

export const arrivalsOrdinalSuffix = (
  rank: number
): "st" | "nd" | "rd" | "th" => {
  const abs = Math.abs(Math.trunc(rank))
  const mod100 = abs % 100
  if (mod100 >= 11 && mod100 <= 13) return "th"
  switch (abs % 10) {
    case 1:
      return "st"
    case 2:
      return "nd"
    case 3:
      return "rd"
    default:
      return "th"
  }
}

export const formatArrivalsRankLabel = (rank: number): string =>
  `${rank}${arrivalsOrdinalSuffix(rank)}`

